create table if not exists public.stripe_invoice_links(id uuid primary key default gen_random_uuid(),stripe_invoice_id text not null unique,stripe_customer_id text,player_id uuid not null references public.players(id) on delete cascade,category text not null check(category in('travel','tournament','other')),travel_trip_id uuid references public.travel_trips(id) on delete set null,description text,amount_due numeric not null default 0,amount_paid numeric not null default 0,status text not null default 'open',due_date date,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.stripe_invoice_links enable row level security;
create policy "owners manage separate stripe invoices" on public.stripe_invoice_links for all to authenticated using(public.is_owner_admin()) with check(public.is_owner_admin());
